  select count(*) into n_productos from productos;
  select count(*) into n_borrar
  from productos p
  where not (p.codigo_producto = any(validos));
  select count(*) into n_mov_borrar
  from movimientos_inventario m
  where not (m.codigo_producto = any(validos));

  raise notice 'Productos actuales: %', n_productos;
  raise notice 'Productos a eliminar: %', n_borrar;
  raise notice 'Movimientos a eliminar: %', n_mov_borrar;

  execute 'drop rule if exists no_delete_movimientos on movimientos_inventario';
  execute 'drop rule if exists no_update_movimientos on movimientos_inventario';

  delete from movimientos_inventario m
  where not (m.codigo_producto = any(validos));

  delete from productos p
  where not (p.codigo_producto = any(validos));

  execute 'create rule no_update_movimientos as on update to movimientos_inventario do instead nothing';
  execute 'create rule no_delete_movimientos as on delete to movimientos_inventario do instead nothing';

  select count(*) into n_productos from productos;
